const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'F(x) = F₀(1 − x/h), 0 ≤ x ≤ h' },
      { kind: 'text', payload: 'F(x)' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: 'h/2' },
      { kind: 'text', payload: 'h' },
      { kind: 'text', payload: 'F₀' },
      { kind: 'text', payload: 'F₀/2' },
      { kind: 'text', payload: '阴影面积 W/(F₀h) = 3/8 = 0.375' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var left = W * 0.12;
    var right = W * 0.10;
    var top = H * 0.12;
    var bottom = H * 0.16;
    var ox = left;
    var oy = H - bottom;
    var plotW = W - left - right;
    var plotH = H - top - bottom;
    var xh = ox + plotW;
    var xh2 = ox + plotW / 2;
    var yF0 = oy - plotH;
    var yF02 = oy - plotH / 2;

    var shade = ['M', ox, oy, 'L', xh2, oy, 'L', xh2, yF02, 'L', ox, yF0, 'Z'];
    var xaxis = visualSdk.arrow(ox, oy, ox + plotW + 28, oy, {});
    var yaxis = visualSdk.arrow(ox, oy, ox, yF0 - 28, {});
    var curve = ['M', ox, yF0, 'L', xh, oy];
    var tickH2 = ['M', xh2, oy - 6, 'L', xh2, oy + 6];
    var tickF02 = ['M', ox - 6, yF02, 'L', ox + 6, yF02];

    return {
      schemaVersion: 1,
      sceneId: 'f-x-linear-area',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'shade', commands: shade },
        { id: 'xaxis', commands: xaxis },
        { id: 'yaxis', commands: yaxis },
        { id: 'curve', commands: curve },
        { id: 'tickH2', commands: tickH2 },
        { id: 'tickF02', commands: tickF02 }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'shade', fill: '#CFE2F3', stroke: { width: 1 } },
          { type: 'path', pathId: 'xaxis', fill: '#26354a', stroke: { width: 2 } },
          { type: 'path', pathId: 'yaxis', fill: '#26354a', stroke: { width: 2 } },
          { type: 'path', pathId: 'curve', fill: '#C0392B', stroke: { width: 3 } },
          { type: 'path', pathId: 'tickH2', fill: '#26354a', stroke: { width: 2 } },
          { type: 'path', pathId: 'tickF02', fill: '#26354a', stroke: { width: 2 } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: ox, y: top * 0.35 }, hAlign: 'left', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: ox + 10, y: yF0 - 10 }, hAlign: 'left', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: ox + plotW + 34, y: oy }, hAlign: 'left', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: ox - 10, y: oy + 6 }, hAlign: 'right', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: xh2, y: oy + 18 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[5].contentId, anchor: { x: xh, y: oy + 18 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[6].contentId, anchor: { x: ox - 10, y: yF0 }, hAlign: 'right', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: metrics[7].contentId, anchor: { x: ox - 10, y: yF02 }, hAlign: 'right', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: metrics[8].contentId, anchor: { x: ox + 12, y: yF02 + 22 }, hAlign: 'left', vAlign: 'middle', color: '#26354a' }
        ]
      }
    };
  }
};
